/// Typed option descriptors (data generated by tools/gen_options.dart).
library;

/// How an option's value is represented in Dart.
enum MpvOptionType {
  /// `yes`/`no` → [bool].
  flag,

  /// Integer, 64-bit integer and byte-size options → [int].
  integer,

  /// Double, float, time and aspect options → [double].
  real,

  /// One of [MpvOption.choices] (some choice options also accept a number
  /// within [MpvOption.min]..[MpvOption.max]) → [String].
  choice,

  /// Everything else (strings, lists, filters, colors, ...) in mpv's own
  /// string syntax → [String].
  string,
}

/// One option of the bundled mpv, with the type its value has in Dart.
final class MpvOption<T extends Object> {
  const MpvOption(
    this.name,
    this.type, {
    this.choices = const [],
    this.min,
    this.max,
  });

  /// Name as used with the property and option APIs.
  final String name;
  final MpvOptionType type;

  /// Allowed values of a [MpvOptionType.choice] option.
  final List<String> choices;

  /// Numeric range, if mpv declares one.
  final num? min;
  final num? max;

  /// Throws [ArgumentError] if [value] is outside the declared choices or
  /// range. mpv validates too; this gives a clearer error earlier.
  void check(T value) {
    if (value is num) {
      if ((min != null && value < min!) || (max != null && value > max!)) {
        throw ArgumentError.value(value, name, 'must be in $min..$max');
      }
    } else if (type == MpvOptionType.choice && value is String) {
      // Numeric strings are allowed for choice options with a range.
      final numeric = num.tryParse(value);
      final inRange =
          numeric != null &&
          (min != null || max != null) &&
          (min == null || numeric >= min!) &&
          (max == null || numeric <= max!);
      if (!choices.contains(value) && !inRange) {
        throw ArgumentError.value(value, name, 'must be one of $choices');
      }
    }
  }

  @override
  String toString() => name;
}
